<script lang="ts">import { onMount } from 'svelte'; import { GraduationCap, Search, Plus, BookOpen, LogOut } from 'lucide-svelte'; import { listCourses, createCourse, deleteCourse } from '../features/courses/api/courseApi'; import { logout } from '../features/auth/api/authApi'; import type { Course } from '../lib/types'; let courses=$state<Course[]>([]); let loading=$state(true); let error=$state(''); let search=$state(''); let mine=$state(false); let showAdd=$state(false); let title=$state(''); let description=$state(''); let profile=$state<any>({});
async function load(){loading=true;error='';try{const r:any=await listCourses();courses=r?.data?.courses||r?.data?.data?.courses||[]; if(typeof localStorage!=='undefined')profile=JSON.parse(localStorage.getItem('profile')||'{}');}catch(e){error=e instanceof Error?e.message:'Gagal memuat kursus';}finally{loading=false;}}
onMount(load); const filtered= $derived(courses.filter(c=>c.title.toLowerCase().includes(search.toLowerCase())&&(!mine||String(c.user_id)===String(profile?.id||profile?.user_id))));
async function add(){if(!title.trim())return;try{await createCourse(title,description);title='';description='';showAdd=false;await load();}catch(e){error=e instanceof Error?e.message:'Gagal menambah kursus';}}
async function remove(c:Course){if(!confirm(`Hapus kursus “${c.title}”?`))return;try{await deleteCourse(c.id);await load();}catch(e){error=e instanceof Error?e.message:'Gagal menghapus kursus';}}
</script>
<div class="shell"><header class="topbar"><a class="brand" href="/"><span class="brand-icon"><GraduationCap size={24}/></span><span>Delcom <b>Courses</b></span></a><nav><a href="/">Semua Kursus</a><a href="/users">Pengguna</a><a href="/profile">Profil</a><a href="/auth/login">Masuk</a></nav></header><main class="container"><section class="hero"><div><span class="eyebrow">RUANG BELAJAR DIGITAL</span><h1>Temukan kursus,<br/><em>kembangkan potensimu.</em></h1><p>Belajar hal baru dan bagikan pengetahuan bersama komunitas Delcom.</p></div><div class="hero-art"><GraduationCap size={96}/><span>LEARN · CREATE · SHARE</span></div></section><div class="section-heading"><div><h2>Jelajahi Kursus</h2><p>Pilih kursus yang sesuai dengan minatmu.</p></div><button class="primary" onclick={()=>showAdd=!showAdd}><Plus size={18}/> Buat Kursus</button></div>
{#if showAdd}<form class="panel form-grid" onsubmit={(e)=>{e.preventDefault();add();}}><label>Judul kursus<input bind:value={title} required placeholder="Contoh: Dasar Pemrograman"/></label><label>Deskripsi<textarea bind:value={description} placeholder="Ceritakan tentang kursus ini"></textarea></label><div class="actions"><button class="primary" type="submit">Simpan Kursus</button><button class="secondary" type="button" onclick={()=>showAdd=false}>Batal</button></div></form>{/if}
<div class="toolbar"><label class="search"><Search size={18}/><input bind:value={search} placeholder="Cari kursus..."/></label><label class="check"><input type="checkbox" bind:checked={mine}/> Kursus saya</label></div>{#if error}<div class="alert">{error}<button onclick={load}>Coba lagi</button></div>{/if}{#if loading}<div class="empty">Memuat kursus...</div>{:else if filtered.length===0}<div class="empty"><BookOpen size={36}/><h3>Belum ada kursus ditemukan</h3><p>Coba kata kunci lain atau buat kursus baru.</p></div>{:else}<div class="course-grid">{#each filtered as c (c.id)}<article class="course-card"><div class="cover">{#if c.cover}<img src={c.cover} alt="Sampul {c.title}"/>{:else}<GraduationCap size={44}/>{/if}<span class="tag">KURSUS</span></div><div class="course-body"><h3>{c.title}</h3><p>{c.description||'Belajar bersama komunitas Delcom.'}</p><div class="card-bottom"><span>{c.students?.length||0} peserta</span><div class="actions"><a class="secondary small" href={'/courses/'+c.id}>Detail</a>{#if String(c.user_id)===String(profile?.id||profile?.user_id)}<button class="danger small" onclick={()=>remove(c)}>Hapus</button>{/if}</div></div></div></article>{/each}</div>{/if}</main><footer>© 2026 Delcom Courses · Belajar bersama, tumbuh bersama.</footer></div>